schema:
CREATE TABLE offerings (item_id TEXT(8), slot_id TEXT(8), term TEXT(6) CHECK (term IN ('Fall', 'Winter', 'Spring', 'Summer')), yr REAL(4, 0) CHECK (yr > 1900 AND yr < 2100), PRIMARY KEY (item_id, slot_id, term, yr));

CREATE TABLE staff (emp_id TEXT(5) PRIMARY KEY, emp_name TEXT(20) NOT NULL);

CREATE TABLE assignments (emp_id TEXT(5), item_id TEXT(8), slot_id TEXT(8), term TEXT(6), yr REAL(4, 0), PRIMARY KEY (emp_id, item_id, slot_id, term, yr), FOREIGN KEY (item_id, slot_id, term, yr) REFERENCES offerings (item_id, slot_id, term, yr) ON DELETE CASCADE, FOREIGN KEY (emp_id) REFERENCES staff (emp_id) ON DELETE CASCADE);
